import{_ as a,o as l,c as i,ag as o}from"./chunks/framework.BYYsWsaA.js";const p=JSON.parse('{"title":"趋势统计 API 与 AI 设置说明","description":"","frontmatter":{},"headers":[],"relativePath":"trend-api-and-ai-settings.md","filePath":"trend-api-and-ai-settings.md","lastUpdated":1773595350000}'),t={name:"trend-api-and-ai-settings.md"};function d(r,e,c,n,h,s){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="趋势统计-api-与-ai-设置说明" tabindex="-1">趋势统计 API 与 AI 设置说明 <a class="header-anchor" href="#趋势统计-api-与-ai-设置说明" aria-label="Permalink to &quot;趋势统计 API 与 AI 设置说明&quot;">​</a></h1><h2 id="_1-日-周趋势统计-api" tabindex="-1">1. 日/周趋势统计 API <a class="header-anchor" href="#_1-日-周趋势统计-api" aria-label="Permalink to &quot;1. 日/周趋势统计 API&quot;">​</a></h2><h3 id="接口" tabindex="-1">接口 <a class="header-anchor" href="#接口" aria-label="Permalink to &quot;接口&quot;">​</a></h3><ul><li><code>GET /api/v1/measurements/trends</code></li></ul><h3 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>用于给后端、控制台或后续 App 提供近阶段健康趋势数据，而不是只看单次测量。</p><h3 id="权限与作用域" tabindex="-1">权限与作用域 <a class="header-anchor" href="#权限与作用域" aria-label="Permalink to &quot;权限与作用域&quot;">​</a></h3><ul><li>普通用户：查看自己的趋势</li><li>管理员：默认查看所有普通用户趋势</li><li>管理员传 <code>user_id</code> 时：查看指定普通用户趋势</li></ul><h3 id="返回结构" tabindex="-1">返回结构 <a class="header-anchor" href="#返回结构" aria-label="Permalink to &quot;返回结构&quot;">​</a></h3><p>接口返回两个维度：</p><ul><li><code>daily</code></li><li><code>weekly</code></li></ul><p>每个时间桶包含：</p><ul><li><code>label</code></li><li><code>measurement_count</code></li><li><code>high_risk_count</code></li><li><code>alert_count</code></li><li><code>avg_heart_rate</code></li><li><code>avg_oxygen</code></li></ul><h3 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h3><p>当前实现使用 Django 查询 + Python 聚合，不依赖额外分析框架。</p><p>这样做的原因：</p><ul><li>当前数据规模不大</li><li>在线 API 需要简单稳定</li><li>SQLite 和 MySQL 都能直接运行</li></ul><h2 id="_2-ai-设置-api" tabindex="-1">2. AI 设置 API <a class="header-anchor" href="#_2-ai-设置-api" aria-label="Permalink to &quot;2. AI 设置 API&quot;">​</a></h2><h3 id="接口-1" tabindex="-1">接口 <a class="header-anchor" href="#接口-1" aria-label="Permalink to &quot;接口&quot;">​</a></h3><ul><li><code>GET /api/v1/ai/settings</code></li><li><code>PUT /api/v1/ai/settings</code></li></ul><h3 id="作用-1" tabindex="-1">作用 <a class="header-anchor" href="#作用-1" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>给管理员提供统一的 AI 配置入口，而不是把 AI 参数散落在代码和环境变量里。</p><h3 id="当前支持字段" tabindex="-1">当前支持字段 <a class="header-anchor" href="#当前支持字段" aria-label="Permalink to &quot;当前支持字段&quot;">​</a></h3><ul><li><code>enabled</code></li><li><code>mode</code></li><li><code>api_base_url</code></li><li><code>api_key</code></li><li><code>model</code></li><li><code>temperature</code></li><li><code>system_prompt</code></li></ul><h3 id="模式说明" tabindex="-1">模式说明 <a class="header-anchor" href="#模式说明" aria-label="Permalink to &quot;模式说明&quot;">​</a></h3><ul><li><p><code>disabled</code> 接口存在，但不视为启用 AI</p></li><li><p><code>template</code> 不调用外部模型，直接返回模板化中文解释</p></li><li><p><code>openai_compatible</code> 调用兼容 OpenAI Chat Completions 的外部模型，失败时自动回退模板解释</p></li></ul><h2 id="_3-llm-解读接口" tabindex="-1">3. LLM 解读接口 <a class="header-anchor" href="#_3-llm-解读接口" aria-label="Permalink to &quot;3. LLM 解读接口&quot;">​</a></h2><h3 id="接口-2" tabindex="-1">接口 <a class="header-anchor" href="#接口-2" aria-label="Permalink to &quot;接口&quot;">​</a></h3><ul><li><code>POST /api/v1/measurements/{measurement_id}/llm-insight</code></li></ul><h3 id="返回策略" tabindex="-1">返回策略 <a class="header-anchor" href="#返回策略" aria-label="Permalink to &quot;返回策略&quot;">​</a></h3><p>无论是否配置外部模型，接口都会返回：</p><ul><li><code>content</code></li><li><code>template_content</code></li><li><code>context</code></li><li><code>prompt</code></li><li><code>source</code></li></ul><h3 id="source-说明" tabindex="-1">source 说明 <a class="header-anchor" href="#source-说明" aria-label="Permalink to &quot;source 说明&quot;">​</a></h3><ul><li><p><code>template</code> 当前使用模板解释</p></li><li><p><code>llm</code> 当前使用外部大模型解释</p></li><li><p><code>template_fallback</code> 原本尝试调用外部大模型，但失败后回退到模板解释</p></li></ul><h2 id="_4-模板化解释为什么要保留" tabindex="-1">4. 模板化解释为什么要保留 <a class="header-anchor" href="#_4-模板化解释为什么要保留" aria-label="Permalink to &quot;4. 模板化解释为什么要保留&quot;">​</a></h2><p>原因很简单：</p><ul><li>毕设演示不能依赖外部接口一定可用</li><li>健康解读必须先有稳定兜底</li><li>模板解释足以支撑一期的中文风险说明</li></ul><p>因此当前策略是：</p><ol><li>规则分析先产出结构化结果</li><li>模板解释负责“面向患者的中文说明”</li><li>配置真实模型后，再让 LLM 替代模板内容</li></ol><h2 id="_5-console-中的-ai-设置页面" tabindex="-1">5. Console 中的 AI 设置页面 <a class="header-anchor" href="#_5-console-中的-ai-设置页面" aria-label="Permalink to &quot;5. Console 中的 AI 设置页面&quot;">​</a></h2><p>控制台新增管理员页面：</p><ul><li><code>http://localhost:5173/ai-settings</code></li></ul><p>用途：</p><ul><li>开关 AI 解读</li><li>选择模式</li><li>配置兼容 OpenAI 的模型地址与 Key</li><li>调整模型名和温度</li><li>自定义系统提示词</li></ul><h2 id="_6-推荐使用方式" tabindex="-1">6. 推荐使用方式 <a class="header-anchor" href="#_6-推荐使用方式" aria-label="Permalink to &quot;6. 推荐使用方式&quot;">​</a></h2><p>当前阶段建议：</p><ul><li>默认启用 <code>template</code></li><li>当你准备接真实 AI 服务时，再切到 <code>openai_compatible</code></li></ul><p>这样可以兼顾：</p><ul><li>稳定性</li><li>演示效果</li><li>后续扩展性</li></ul>',49)])])}const m=a(t,[["render",d]]);export{p as __pageData,m as default};
